{"type":"tool","tool":"write","callID":"write_4","state":{"status":"completed","input":{"filePath":"/Users/onesteppplusgmai.com/Dev/vulcan-k3/black-buck.html","content":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>OPERATION BLACK BUCK — The 6,600-Mile Raid</title>
<style>
  :root{
    --bg:#04101c; --ink:#d7e9f7; --dim:#7fa3bd; --faint:#4a6a82;
    --cyan:#6ee7ff; --amber:#ffb454; --green:#7dffa8; --red:#ff6a5e;
    --panel:rgba(6,17,28,.86); --line:rgba(110,231,255,.16);
    --mono:"SF Mono",ui-monospace,Menlo,Consolas,monospace;
    --sans:"Avenir Next","Segoe UI",system-ui,-apple-system,sans-serif;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{height:100%;overflow:hidden;background:var(--bg);color:var(--ink);
    font-family:var(--sans);-webkit-font-smoothing:antialiased}
  #map{position:fixed;inset:0;display:block;cursor:grab}
  #map.drag{cursor:grabbing}
  #vig{position:fixed;inset:0;pointer-events:none;
    background:radial-gradient(ellipse at 42% 44%,transparent 55%,rgba(0,4,10,.55) 100%)}

  #panel{position:fixed;top:0;right:0;bottom:86px;width:388px;padding:16px 16px 10px;
    background:linear-gradient(180deg,var(--panel),rgba(4,12,22,.93));
    border-left:1px solid var(--line);backdrop-filter:blur(14px);
    display:flex;flex-direction:column;gap:10px;overflow:hidden}
  .p-title{font-size:10.5px;letter-spacing:.32em;color:var(--dim);font-weight:600}
  .p-big{font-size:19px;font-weight:800;letter-spacing:.05em;color:#fff}
  .p-big small{color:var(--cyan);font-size:11px;letter-spacing:.2em;display:block;margin-top:2px}
  .clockrow{display:flex;justify-content:space-between;align-items:baseline;
    border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:7px 2px}
  .clock{font-family:var(--mono);font-size:29px;font-weight:700;color:var(--cyan);
    text-shadow:0 0 18px rgba(110,231,255,.45);letter-spacing:.04em}
  .clock small{font-size:11px;color:var(--dim);text-shadow:none}
  .elapsed{font-family:var(--mono);font-size:12.5px;color:var(--dim);text-align:right;line-height:1.5}
  .elapsed b{color:var(--ink)}
  #phase{font-size:12px;font-weight:700;letter-spacing:.16em;color:var(--amber);
    text-transform:uppercase;min-height:16px;text-shadow:0 0 14px rgba(255,180,84,.35)}
  .fuelwrap{border:1px solid var(--line);border-radius:10px;padding:9px 12px 10px;
    background:rgba(10,26,40,.5)}
  .fueltop{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:6px}
  .fueltop span{font-size:10px;letter-spacing:.24em;color:var(--dim);font-weight:600}
  #fuelnum{font-family:var(--mono);font-size:20px;font-weight:700;color:#fff}
  #fuelnum small{font-size:11px;color:var(--dim)}
  .gauge{height:14px;border-radius:7px;background:#0a1826;border:1px solid var(--line);overflow:hidden}
  #fuelfill{height:100%;width:100%;border-radius:6px;
    background:linear-gradient(90deg,#ff6a5e 0%,#ffb454 22%,#6ee7ff 55%,#8ff7ff 100%);
    transition:width .12s linear;box-shadow:0 0 14px rgba(110,231,255,.35)}
  #xfer{margin-top:6px;font-family:var(--mono);font-size:11.5px;color:var(--green);
    min-height:15px;text-shadow:0 0 12px rgba(125,255,168,.5)}
  .bingo{color:var(--red) !important;animation:blink 1s steps(2) infinite;font-weight:700}
  @keyframes blink{50%{opacity:.15}}
  .grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}
  .cell{border:1px solid var(--line);border-radius:8px;padding:6px 10px;background:rgba(10,26,40,.35)}
  .cell .k{font-size:8.5px;letter-spacing:.2em;color:var(--faint);font-weight:700}
  .cell .v{font-family:var(--mono);font-size:16px;font-weight:700;color:var(--ink);margin-top:2px}
  .cell .v small{font-size:10px;color:var(--dim)}
  #log{flex:1;overflow-y:auto;border:1px solid var(--line);border-radius:10px;
    background:rgba(8,20,33,.55);padding:6px 4px 6px 8px;scrollbar-width:thin;
    scrollbar-color:#21465e transparent}
  #log::-webkit-scrollbar{width:5px}#log::-webkit-scrollbar-thumb{background:#21465e;border-radius:3px}
  .le{padding:5px 8px 5px 10px;border-left:2px solid transparent;border-radius:4px;
    cursor:pointer;margin-bottom:2px;transition:background .15s}
  .le:hover{background:rgba(110,231,255,.07)}
  .le.done{opacity:.5}
  .le.now{border-left-color:var(--cyan);background:rgba(110,231,255,.09);opacity:1}
  .le .lt{font-family:var(--mono);font-size:10px;color:var(--cyan);letter-spacing:.06em}
  .le .lh{font-size:12px;font-weight:700;color:var(--ink);margin:1px 0}
  .le .ld{font-size:10.5px;color:var(--dim);line-height:1.45}
  .le.hot .lh{color:var(--amber)}
  .controls{display:flex;gap:5px;align-items:center;flex-wrap:wrap}
  button{font-family:var(--sans);background:rgba(110,231,255,.08);color:var(--ink);
    border:1px solid var(--line);border-radius:8px;padding:7px 9px;font-size:11px;
    font-weight:700;letter-spacing:.06em;cursor:pointer;transition:all .15s}
  button:hover{background:rgba(110,231,255,.18);border-color:rgba(110,231,255,.45)}
  button.on{background:var(--cyan);color:#04222e;border-color:var(--cyan);
    box-shadow:0 0 16px rgba(110,231,255,.4)}
  #playBtn{min-width:72px}
  .spd{font-family:var(--mono);padding:7px 7px}
  .hint{font-size:9.5px;color:var(--faint);letter-spacing:.04em;line-height:1.55}

  #tl{position:fixed;left:0;right:0;bottom:0;height:86px;padding:10px 22px 12px;
    background:linear-gradient(0deg,rgba(4,11,20,.96),rgba(5,14,24,.88));
    border-top:1px solid var(--line);backdrop-filter:blur(12px)}
  #tltrack{position:relative;height:30px;margin-top:20px;border-radius:15px;
    background:rgba(110,231,255,.06);border:1px solid var(--line);cursor:pointer}
  #tlfill{position:absolute;left:0;top:0;bottom:0;border-radius:15px;
    background:linear-gradient(90deg,rgba(110,231,255,.12),rgba(110,231,255,.4));
    box-shadow:0 0 18px rgba(110,231,255,.25);width:0;pointer-events:none}
  .dwell{position:absolute;top:0;bottom:0;background:rgba(255,180,84,.10);
    border-left:1px solid rgba(255,180,84,.22);border-right:1px solid rgba(255,180,84,.22);
    pointer-events:none}
  .mk{position:absolute;top:-7px;width:11px;height:11px;border-radius:50%;
    background:#0b2233;border:2px solid var(--faint);transform:translateX(-50%);cursor:pointer;
    transition:transform .15s,border-color .15s;z-index:2}
  .mk:hover{transform:translateX(-50%) scale(1.55);border-color:var(--cyan)}
  .mk.hot{border-color:var(--amber);background:#3a2410}
  .mk.passed{border-color:var(--cyan);background:var(--cyan)}
  #tlhead{position:absolute;top:-16px;transform:translateX(-50%);font-family:var(--mono);
    font-size:10px;color:var(--cyan);white-space:nowrap;letter-spacing:.1em;pointer-events:none}
  #tlcur{position:absolute;top:-5px;width:3px;height:22px;background:var(--cyan);
    transform:translateX(-50%);box-shadow:0 0 10px var(--cyan);border-radius:2px;z-index:3;
    pointer-events:none}
  .tllab{position:absolute;top:34px;transform:translateX(-50%);font-size:9.5px;
    color:var(--faint);letter-spacing:.1em;font-family:var(--mono);white-space:nowrap;
    pointer-events:none}

  .ovl{position:fixed;inset:0;z-index:50;display:flex;align-items:center;justify-content:center;
    background:radial-gradient(ellipse at center,rgba(5,16,28,.9),rgba(2,6,12,.97));
    backdrop-filter:blur(6px);transition:opacity .6s}
  .ovl.hide{opacity:0;pointer-events:none}
  .card{max-width:780px;padding:42px 50px;text-align:center;border:1px solid var(--line);
    border-radius:18px;background:rgba(6,17,29,.78);box-shadow:0 0 80px rgba(110,231,255,.08)}
  .kick{font-size:11px;letter-spacing:.42em;color:var(--amber);font-weight:700;margin-bottom:14px}
  h1{font-size:42px;letter-spacing:.09em;color:#fff;font-weight:800;line-height:1.12;
    text-shadow:0 0 40px rgba(110,231,255,.35)}
  h1 span{color:var(--cyan)}
  .sub{margin:16px auto 0;max-width:620px;color:var(--dim);font-size:14px;line-height:1.75}
  .sub b{color:var(--ink)}
  .stats{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin:26px 0 6px}
  .chip{border:1px solid var(--line);border-radius:10px;padding:10px 15px;background:rgba(10,26,40,.6)}
  .chip .cv{font-family:var(--mono);font-size:18px;font-weight:700;color:var(--cyan)}
  .chip .ck{font-size:8.5px;letter-spacing:.18em;color:var(--faint);font-weight:700;margin-top:2px}
  #startBtn,#againBtn{margin-top:24px;font-size:15px;letter-spacing:.26em;padding:15px 42px;
    border-radius:12px;background:var(--cyan);color:#032028;border:none;
    box-shadow:0 0 40px rgba(110,231,255,.45);font-weight:800}
  #startBtn:hover,#againBtn:hover{transform:translateY(-2px);box-shadow:0 0 60px rgba(110,231,255,.7)}
  .fine{margin-top:18px;font-size:10.5px;color:var(--faint);letter-spacing:.05em;line-height:1.7}
</style>
</head>
<body>
<canvas id="map"></canvas>
<div id="vig"></div>

<aside id="panel">
  <div>
    <div class="p-title">FALKLANDS WAR · 30 APR – 1 MAY 1982</div>
    <div class="p-big">OPERATION BLACK BUCK 1<small>VULCAN XM607 · VICTOR TANKER CASCADE</small></div>
  </div>
  <div class="clockrow">
    <div class="clock" id="zulu">23:50<small>Z</small></div>
    <div class="elapsed">ELAPSED <b id="elap">T+00:00</b><br><span id="daynote">30 APR · WIDEAWAKE</span></div>
  </div>
  <div id="phase">PRE-LAUNCH — WIDEAWAKE AIRFIELD</div>
  <div class="fuelwrap">
    <div class="fueltop"><span>XM607 FUEL STATE</span><div id="fuelnum">74,000 <small>LB</small></div></div>
    <div class="gauge"><div id="fuelfill"></div></div>
    <div id="xfer">&nbsp;</div>
  </div>
  <div class="grid">
    <div class="cell"><div class="k">DIST TO STANLEY</div><div class="v" id="dtg">—</div></div>
    <div class="cell"><div class="k">GND SPEED</div><div class="v" id="gs">—</div></div>
    <div class="cell"><div class="k">ALTITUDE</div><div class="v" id="alt">—</div></div>
    <div class="cell"><div class="k">SOUTHBOUND FORCE</div><div class="v" id="frm">—</div></div>
  </div>
  <div id="log"></div>
  <div class="controls">
    <button id="playBtn">❚❚ PAUSE</button>
    <button class="spd" data-s="1">1×</button>
    <button class="spd on" data-s="4">4×</button>
    <button class="spd" data-s="12">12×</button>
    <button class="spd" data-s="30">30×</button>
    <button id="nextBtn" title="Jump to next event">NEXT ▶</button>
    <button id="reBtn" title="Restart mission">↺</button>
    <button id="fitBtn" title="Recenter map">◎</button>
  </div>
  <div class="hint">SPACE play/pause · ←/→ prev/next event · drag &amp; wheel to explore the map ·
  click log entries &amp; timeline dots to jump. Speed = mission-minutes per second;
  time auto-slows at every refuelling &amp; the attack.</div>
</aside>

<div id="tl">
  <div id="tltrack">
    <div id="tlfill"></div>
    <div id="tlcur"></div>
    <div id="tlhead">23:50Z</div>
  </div>
</div>

<div class="ovl" id="intro">
  <div class="card">
    <div class="kick">ASCENSION ISLAND → PORT STANLEY · 3,300 NAUTICAL MILES EACH WAY</div>
    <h1>OPERATION<br>BLACK BUCK <span>ONE</span></h1>
    <div class="sub">
      A single <b>Avro Vulcan</b> against the farthest target in RAF history. It could not get
      there and back — so <b>eleven Victor tankers</b> launched with it, refuelling the bomber
      <b>and each other</b> in a cascading relay down the South Atlantic, peeling away one by one
      until a lone tanker made the final top-off inside a thunderstorm — and then had to be
      rescued itself. Watch the fuel gauge. In this mission, fuel is the plot.
    </div>
    <div class="stats">
      <div class="chip"><div class="cv">6,600</div><div class="ck">NM ROUND TRIP</div></div>
      <div class="chip"><div class="cv">15</div><div class="ck">VICTOR SORTIES</div></div>
      <div class="chip"><div class="cv">18</div><div class="ck">REFUELLINGS PLANNED</div></div>
      <div class="chip"><div class="cv">7+1</div><div class="ck">VULCAN TOP-OFFS</div></div>
      <div class="chip"><div class="cv">21</div><div class="ck">× 1,000 LB BOMBS</div></div>
      <div class="chip"><div class="cv">15h03m</div><div class="ck">FLIGHT TIME</div></div>
    </div>
    <button id="startBtn">▶&nbsp;&nbsp;BEGIN MISSION</button>
    <div class="fine">Animated reconstruction · real geography &amp; mission timeline (23:50Z – 14:52Z) ·
    aircraft, markers and the Stanley runway exaggerated for readability · time compressed,
    with automatic slow-motion at key events</div>
  </div>
</div>

<div class="ovl hide" id="outro">
  <div class="card">
    <div class="kick">1452Z · 1 MAY 1982 · WIDEAWAKE AIRFIELD</div>
    <h1>MISSION <span>COMPLETE</span></h1>
    <div class="sub">
      XM607 is down after <b>15 hours 3 minutes</b> and <b>~6,600 nautical miles</b> — the longest
      bombing mission ever flown at that time. One crater in Stanley's runway, from one bomb in
      twenty-one. The Vulcan took on fuel <b>eight times</b>; four more Victors flew as the recovery
      wave — including one sent to refuel a tanker that had given away too much. Every aircraft came home.
    </div>
    <div class="stats">
      <div class="chip"><div class="cv">1</div><div class="ck">RUNWAY CRATER</div></div>
      <div class="chip"><div class="cv">~130,000</div><div class="ck">LB FUEL TO XM607</div></div>
      <div class="chip"><div class="cv">2</div><div class="ck">TANKERS RESCUED</div></div>
      <div class="chip"><div class="cv">0</div><div class="ck">AIRCRAFT LOST</div></div>
    </div>
    <button id="againBtn">↺&nbsp;&nbsp;FLY IT AGAIN</button>
  </div>
</div>

<script>
"use strict";
/* =====================================================================
   OPERATION BLACK BUCK 1 — animated reconstruction
   Real lat/lng geography. Historical timeline: launch 2350Z, attack
   ~0741Z, "superfuse" 0746Z, landing 1452Z. Icons exaggerated.
   ===================================================================== */

const D2R=Math.PI/180;
const REFLAT=-29, K=Math.cos(REFLAT*D2R);        // world: x=lng*K, y=-lat
const ASC=[-7.956,-14.393];                       // Wideawake, Ascension Island
const STN=[-51.690,-57.777];                      // Stanley Airport
const toW=([la,lo])=>[lo*K,-la];

function gc(a,b,n){                               // great-circle densify
  const v=p=>{const la=p[0]*D2R,lo=p[1]*D2R;
    return [Math.cos(la)*Math.cos(lo),Math.cos(la)*Math.sin(lo),Math.sin(la)];};
  const A=v(a),B=v(b),ang=Math.acos(Math.max(-1,Math.min(1,A[0]*B[0]+A[1]*B[1]+A[2]*B[2])));
  const out=[];
  for(let i=0;i<=n;i++){
    const f=i/n,s=Math.sin((1-f)*ang)/Math.sin(ang),c=Math.sin(f*ang)/Math.sin(ang);
    const x=A[0]*s+B[0]*c,y=A[1]*s+B[1]*c,z=A[2]*s+B[2]*c;
    out.push([Math.atan2(z,Math.hypot(x,y))/D2R,Math.atan2(y,x)/D2R]);
  }
  return out;
}
function makeTrack(waypoints,per){
  let pts=[];
  for(let i=0;i<waypoints.length-1;i++){
    const seg=gc(waypoints[i],waypoints[i+1],per||24);
    if(i)seg.shift();
    pts=pts.concat(seg);
  }
  const cum=[0];
  for(let i=1;i<pts.length;i++){
    const dla=pts[i][0]-pts[i-1][0],dlo=pts[i][1]-pts[i-1][1];
    const mLa=(pts[i][0]+pts[i-1][0])/2;
    cum.push(cum[i-1]+60*Math.hypot(dla,dlo*Math.cos(mLa*D2R)));
  }
  return {
    pts,cum,len:cum[cum.length-1],
    at(d){                                        // world [x,y] at distance d nm
      d=Math.max(0,Math.min(this.len,d));
      let lo=0,hi=cum.length-1;
      while(lo<hi-1){const m=(lo+hi)>>1;if(cum[m]<=d)lo=m;else hi=m;}
      const f=(d-cum[lo])/Math.max(1e-9,cum[hi]-cum[lo]);
      const a=toW(pts[lo]),b=toW(pts[hi]);
      return [a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f];
    }
  };
}
const OUT=makeTrack([ASC,STN],170);                       // ~3,300 nm outbound
const RET=makeTrack([STN,[-46,-53.5],[-39,-48],[-29,-40.5],[-21,-31],[-13.5,-22],ASC],26);
const RDV_D=makeTrack([STN,[-46,-53.5],[-39,-48],[-29,-40.5]],26).len;  // rendezvous dist

/* simplified, stylised coastline */
const SOUTH_AMERICA=[
  [5.3,-50.0],[2.5,-50.8],[0.0,-50.0],[-1.5,-48.5],[-1.0,-44.5],[-2.8,-41.5],[-3.7,-38.5],
  [-4.8,-36.5],[-5.8,-35.0],[-7.0,-34.8],[-8.2,-34.9],[-9.7,-36.0],[-11.0,-37.1],[-13.0,-38.5],
  [-14.5,-39.0],[-16.2,-39.1],[-18.0,-39.7],[-20.3,-40.3],[-22.0,-41.0],[-23.0,-43.2],
  [-23.9,-45.4],[-25.0,-47.6],[-26.2,-48.6],[-27.6,-48.5],[-28.6,-48.9],[-30.0,-50.2],
  [-32.0,-52.0],[-33.7,-53.4],[-34.5,-54.0],[-35.0,-55.6],[-35.6,-56.0],[-37.0,-56.8],
  [-38.0,-57.6],[-38.8,-60.0],[-38.8,-62.1],[-40.3,-62.3],[-40.8,-63.0],[-41.0,-64.2],
  [-42.0,-63.7],[-42.8,-65.0],[-43.4,-65.1],[-44.4,-65.3],[-45.2,-66.3],[-45.9,-67.5],
  [-47.0,-66.9],[-47.8,-65.9],[-49.3,-67.7],[-50.0,-68.5],[-50.9,-69.0],[-51.6,-69.1],
  [-52.4,-68.4],[-53.4,-68.0],[-54.4,-66.5],[-54.8,-65.6],[-55.0,-66.5]
];
const W_FALKLAND=[[-51.30,-60.55],[-51.42,-59.65],[-51.75,-59.35],[-52.05,-59.85],[-52.18,-60.60],[-51.90,-61.05],[-51.50,-61.00]];
const E_FALKLAND=[[-51.25,-58.95],[-51.55,-58.00],[-51.85,-57.75],[-52.10,-58.35],[-52.30,-59.30],[-51.95,-59.90],[-51.60,-59.55]];
const S_GEORGIA=[-54.35,-36.6];

/* ---------------- mission schedule (minutes after 23:50Z) ---------------- */
const GS_OUT=440,GS_RET=480;                      // knots
const VULCAN_T0=12;                               // XM607 last off the runway
const BR_D=[550,1000,1450,1850,2250,2600,3000];   // AAR brackets, nm from Ascension
const BR_T=BR_D.map(d=>VULCAN_T0+d/GS_OUT*60);    // Vulcan time at each bracket
const ATK_T=VULCAN_T0+OUT.len/GS_OUT*60;          // over target ~0741Z
const RET_T0=ATK_T+4;
const LAND_T=RET_T0+RET.len/GS_RET*60;            // ~1453Z
const RDV_T=RET_T0+RDV_D/GS_RET*60;               // Vulcan at rendezvous ~1100Z
const TUX_LEAVE=BR_T[6]+3;                        // Tuxford turns north
const TUX_GW_D=1100;                              // get-well point, nm from Ascension
const TUX_GW_T=TUX_LEAVE+(3000-TUX_GW_D)/GS_OUT*60;   // ~1123Z
const TUX_LAND=TUX_LEAVE+3000/GS_OUT*60;              // ~1353Z (14h03m airborne)
const SEY_T0=TUX_GW_T-TUX_GW_D/460*60;
const NEAL_T0=RDV_T-(RET.len-RDV_D)/450*60;
const NIM_T0=RDV_T-300;                           // Nimrod launched hours ahead

function KF(t,d,trk,alt){return{t,d,trk,alt};}
function southChain(launch,peelIdx){              // Victor southbound, peeling at bracket peelIdx (-1: stays to the end)
  const k=[KF(launch,0,'out',0),KF(launch+32,250,'out',29000)];
  for(let i=0;i<BR_D.length;i++){
    k.push(KF(BR_T[i],BR_D[i],'out',29000));
    if(i===peelIdx){
      k.push(KF(BR_T[i]+4,BR_D[i]+26,'out',29000));       // wide turn
      const back=BR_D[i]/GS_OUT*60;
      k.push(KF(BR_T[i]+4+back-15,120,'out',8000));
      k.push(KF(BR_T[i]+4+back,0,'out',0));
      return k;
    }
  }
  return k;
}
const AC=[];
const PEELS=[[10,11],[8,9],[6,7],[4,5],[3],[2],[]];      // V-numbers peeling per bracket
for(let i=0;i<11;i++){
  const vn=i+1;
  let peelIdx=-1;
  for(let b=0;b<PEELS.length;b++)if(PEELS[b].includes(vn))peelIdx=b;
  const name=vn===1?"XL189 · TUXFORD":vn===2?"BIGLANDS":"VICTOR K."+vn;
  AC.push({id:"V"+vn,name,type:"victor",kf:southChain(i,peelIdx)});
}
