+  $("outro").classList.add("hide");$("intro").classList.add("hide");
+  camTo(fitCam(),2);lastLogIdx=-2;updateLog();setPlayBtn();
+}
+$("startBtn").onclick=()=>{$("intro").classList.add("hide");started=true;playing=true;setPlayBtn();};
+$("againBtn").onclick=restart;
+$("reBtn").onclick=restart;
+$("fitBtn").onclick=()=>{camState=0;cam.manual=-1e9;camTo(fitCam(),1.5);};
+$("playBtn").onclick=()=>{
+  if(!started){$("intro").classList.add("hide");started=true;}
+  if(finished){restart();return;}
+  playing=!playing;setPlayBtn();
+};
+document.querySelectorAll(".spd").forEach(b=>{
+  b.onclick=()=>{
+    speed=parseFloat(b.dataset.s);
+    document.querySelectorAll(".spd").forEach(x=>x.classList.toggle("on",x===b));
+  };
+});
+function nextEvent(dir){
+  const list=dir>0?EV:[...EV].reverse();
+  const n=list.find(x=>dir>0?x.t>t+0.5:x.t<t-1);
+  if(n)seek(n.t+0.01);
+}
+$("nextBtn").onclick=()=>nextEvent(1);
+addEventListener("keydown",e=>{
+  if(e.code==="Space"){e.preventDefault();$("playBtn").click();}
+  else if(e.code==="ArrowRight"){e.preventDefault();nextEvent(1);}
+  else if(e.code==="ArrowLeft"){e.preventDefault();nextEvent(-1);}
+  else if(e.code==="KeyR")restart();
+});
+document.addEventListener("visibilitychange",()=>{lastReal=performance.now();});
+
+/* ---------------- main loop ---------------- */
+function camTriggers(tOld,tNew){
+  if(performance.now()-cam.manual<12000)return;
+  if(camState===0&&tOld<ATK_T-8&&tNew>=ATK_T-8){camState=1;camTo(attackCam(),6);}
+  else if(camState===1&&tNew>=ATK_T+11){camState=0;camTo(fitCam(),7);}
+}
+function render(now){
+  drawOcean(now);
+  drawGrat();
+  drawRoutes();
+  drawLand();
+  drawPlaces(now);
+  drawAttack(now);
+  drawLinks(now);
+  drawAircraft(now);
+  drawFlashes();
+  drawScaleCompass();
+  const r=mapRect();
+  txt("OPERATION BLACK BUCK 1 \u00B7 SOUTH ATLANTIC \u00B7 30 APR \u2013 1 MAY 1982",
+    r.x+18,r.y+18,10,"rgba(127,163,189,.6)","left",700);
+}
+function frame(now){
+  requestAnimationFrame(frame);
+  const dt=Math.min(0.05,(now-lastReal)/1000);lastReal=now;
+  if(playing&&started&&!finished){
+    const nt=t+dt*speed*warp(t);
+    camTriggers(t,nt);
+    t=Math.min(LAND_T,nt);
+    if(t>=LAND_T){finished=true;playing=false;setPlayBtn();$("outro").classList.remove("hide");}
+  }
+  camStep(now);
+  render(now);
+  updateUI();
+}
+buildLog();buildTimeline();updateLog();setPlayBtn();
+requestAnimationFrame(frame);
 </script>
