    const leg=ac.legs[li];
    if(t>=leg.t0) f-=leg.burn*STEP;
    for(const c of CONTACTS){
      if(t<c.t0||t>c.t1) continue;
      const ci=CONTACTS.indexOf(c);
      if(c.failed) continue;
      if(c.from===ac.id){const give=Math.min(c.rate*STEP, Math.max(0,f-1500)); f-=give; given+=give; c.done[k]= (c.done[k-1]||0)+give; }
      else if(c.to===ac.id){const room=Math.max(0,ac.cap-f); const take=Math.min(c.rate*STEP,room); f+=take; recv+=take; c.done[k]=(c.done[k-1]||0)+take;}
    }
    f=Math.max(0,Math.min(ac.cap,f));
    ac.fuelArr[k]=f; ac.givenArr[k]=given; ac.recvArr[k]=recv;
  }
});
