function acState(ac,t){
  const L=ac.legs;
  if(t<L[0].t0) return {phase:'STANDBY',alt:0,pos:null};
  if(t>=L[L.length-1].t1){
    const last=L[L.length-1];
    return {phase:'LANDED',alt:0,pos:proj(last.b)};
  }
  let leg=L[L.length-1];
  for(const g of L){ if(t<=g.t1){leg=g;break;} }
  const u=leg.t1>leg.t0?Math.max(0,Math.min(1,(t-leg.t0)/(leg.t1-leg.t0))):1;
  let ll;
  if(leg.hold){const a=u*Math.PI*8; ll=[leg.a[0]+0.16*Math.sin(a), leg.a[1]+0.22*Math.cos(a)];}
  else ll=slerpLL(leg.a,leg.b,u);
  const alt=leg.alt0+(leg.alt1-leg.alt0)*smooth(u);
  return {phase:leg.tag,alt,pos:proj(ll),ll,leg,u};
}
function headingOf(ac,t){
  const s0=acState(ac,t), s1=acState(ac,t+0.6);
  if(!s0.pos||!s1.pos) return 0;
  return Math.atan2(s1.pos[1]-s0.pos[1], s1.pos[0]-s0.pos[0])*180/Math.PI+90;
}
const idx=t=>Math.max(0,Math.min(N,Math.round(t/STEP)));

