function statusText(ac,t){
  const f=ac.fuelArr[idx(t)];
  if(t<ac.legs[0].t0) return {s:'STANDBY · WIDEAWAKE',c:''};
  if(t>=ac.legs[ac.legs.length-1].t1){
    const e=ac.end;
    return {s:e, c:e.includes('FUME')?'crit':e.includes('ABORT')?'warn':'good'};
  }
  for(const c of CONTACTS){
    if(t>=c.t0&&t<=c.t1&&(c.from===ac.id||c.to===ac.id))
      return c.failed?{s:'PROBE FAILURE',c:'crit'}:{s:'REFUELLING',c:'refuel'};
  }
  const st=acState(ac,t).phase;
  const map={CLIMB:'CLIMBING OUT',CRUISE:'EN ROUTE',RTB:'RETURNING','ABORT RTB':'ABORT — RTB',
    'LOW LEVEL':'LOW LEVEL 300 FT','BOMB RUN':'BOMB RUN','ESCAPE':'ESCAPE TURN',DESCENT:'DESCENDING',
    HOLD:'HOLDING','ON STATION':'ON STATION','RE-TASK S':'RE-TASKED SOUTH','LANDING':'APPROACH','PROBE FAIL':'PROBE FAILURE'};
  let cls='';
  if(st==='PROBE FAIL') cls='crit';
  if(f<8000) cls='crit'; else if(f<20000) cls='warn';
  return {s:map[st]||st,c:cls};
}

