function missionClock(t){
  const total=2350*100 + t;
  const mins=Math.round(total)%1440;
  const day=Math.floor(total/1440);
  const hh=Math.floor(mins/60), mm=mins%60;
  const dstr=day===0?'30 APR':'01 MAY';
  const sHH=Math.floor(((hh+21)%24)), sDay=(hh+21)>=24?(day+1):day;
  const sdstr=sDay===0?'30 APR':sDay===1?'01 MAY':'02 MAY';
  return {z:`${dstr} · ${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}Z`,
          s:`STANLEY ${sdstr} ${String(sHH).padStart(2,'0')}:${String(mm).padStart(2,'0')}`,
          el:`T+${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`};
}

function frame(now){
  const dt=Math.min(0.1,(now-lastFrame)/1000); lastFrame=now;
  if(playing) setT(simT+dt*speed/60);
  const t=simT, k=idx(t);

  AIRCRAFT.forEach(ac=>{
    const st=acState(ac,t);
    const active=st.pos && t>=ac.legs[0].t0 && t<ac.legs[ac.legs.length-1].t1;
    if(active){
      ac.g.setAttribute('opacity',1);
      ac.g.setAttribute('transform',`translate(${st.pos[0]},${st.pos[1]}) rotate(${headingOf(ac,t)})`);
      ac.label.textContent=ac.id===selected?ac.cs:'';
      const lastP=ac.trailPts[ac.trailPts.length-1];
      if(!lastP||t-lastP.t>=3){ac.trailPts.push({x:st.pos[0],y:st.pos[1],t}); if(ac.trailPts.length>140)ac.trailPts.shift();}
      ac.trail.setAttribute('d',ac.trailPts.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+' '+p.y.toFixed(1)).join(''));
      ac.trail.setAttribute('opacity',ac.id===selected?0.85:0.4);
      ac.halo.setAttribute('opacity',ac.id===selected?0.9:0);
    } else {
      ac.g.setAttribute('opacity', t>=ac.legs[ac.legs.length-1].t1?0.25:0);
      if(t>=ac.legs[ac.legs.length-1].t1){
        const [x,y]=proj(ac.legs[ac.legs.length-1].b);
        ac.g.setAttribute('transform',`translate(${x},${y}) rotate(90)`);
        ac.label.textContent='';
      }
      ac.trail.setAttribute('opacity',0);
    }
    const row=rowMap[ac.id];
    const f=ac.fuelArr[k], pct=f/ac.cap*100;
    const fb=row.querySelector('div div');
    fb.style.width=pct+'%'; fb.className=pct<11?'crit':pct<25?'low':'';
    const stx=row.querySelector('.st');
    const stt=statusText(ac,t);
    stx.textContent=stt.s; stx.className='st '+stt.c;
  });

  contactEls.forEach((ce,i)=>{
    const c=ce.c;
    if(t>=c.t0&&t<=c.t1){
